    "# PARAMETERS\n",
    "\n",
    "NUM_LAYERS = 6\n",
    "HIDDEN_DIM = 512\n",
    "GAMMA = 2.0\n",
    "EPOCHS = 30\n",
    "TRAIN_SAMPLES = None # None for the whole test set, and specify a smaller number to run test\n",
