    "# First, train the token_type model\n",
    "\n",
    "train(\n",
    "    split=\"test\",\n",
    "    num_classes=12,\n",
    "    random_seed=42,\n",
    "    device=\"mps\",\n",
    "    train_type=\"e2e\",\n",
    "    cache_dir=\".cache\",\n",
    "    train_split=0.8,\n",
    "    hidden_dim=HIDDEN_DIM,\n",
    "    num_layers=NUM_LAYERS,\n",
    "    max_len=512,\n",
    "    learning_rate=2e-4,\n",
    "    gamma=GAMMA,\n",
    "    batch_size=16,\n",
    "    epochs=EPOCHS,\n",
    "    model_save_dir=\"models\",\n",
    "    end_idx=TRAIN_SAMPLES,\n",
    ")"
